from __future__ import annotations


def dashboard_html() -> str:
    return r'''<!doctype html>
<html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Crumblr Static Trainer</title>
<style>
:root{--bg:#07111f;--panel:#0d1b2b;--line:#20354b;--text:#eef7ff;--muted:#91a7ba;--cyan:#42d9e8;--green:#55df91;--red:#ff7585;--amber:#ffc967}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 15% 0,#12344a 0,transparent 34%),var(--bg);color:var(--text);font:15px/1.45 Inter,Segoe UI,sans-serif}.shell{max-width:1180px;margin:auto;padding:24px}header{display:flex;justify-content:space-between;align-items:center;gap:18px;margin-bottom:22px}h1{font-size:25px;margin:0}h2{font-size:17px;margin:0 0 14px}p{margin:5px 0;color:var(--muted)}.badge{border:1px solid var(--line);border-radius:99px;padding:7px 11px;color:var(--muted)}.badge.ok{color:var(--green);border-color:#256747}.grid{display:grid;grid-template-columns:360px 1fr;gap:18px}.panel{background:linear-gradient(145deg,#102337,#0a1726);border:1px solid var(--line);border-radius:16px;padding:18px;box-shadow:0 16px 40px #0004}.stack{display:grid;gap:14px}.slot{border:1px dashed #35536e;border-radius:13px;padding:15px}.slot.ready{border-style:solid;border-color:#277955;background:#0b2a2455}.slot strong{display:block;margin-bottom:4px}.slot small{display:block;color:var(--muted);word-break:break-word}.row{display:flex;gap:9px;flex-wrap:wrap;align-items:center}input[type=password]{width:100%;background:#07121f;color:var(--text);border:1px solid var(--line);border-radius:10px;padding:11px}input[type=file]{display:none}button,.filebtn{cursor:pointer;border:0;border-radius:10px;padding:11px 14px;background:var(--cyan);color:#03232a;font-weight:750;display:inline-block}button.secondary,.filebtn.secondary{background:#172d42;color:var(--text);border:1px solid #2a475f}button:disabled{opacity:.4;cursor:not-allowed}.start{width:100%;font-size:16px;padding:14px}.error{color:var(--red);min-height:20px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:15px}.metric{background:#071522;border:1px solid var(--line);border-radius:12px;padding:13px}.metric span{color:var(--muted);font-size:12px}.metric strong{display:block;font-size:21px;margin-top:4px}.chart{height:310px;background:#071522;border:1px solid var(--line);border-radius:13px;padding:10px;position:relative}.chart svg{width:100%;height:100%;overflow:visible}.legend{position:absolute;top:12px;left:16px;color:var(--muted);font-size:12px}.loop{display:grid;grid-template-columns:repeat(6,1fr);gap:7px;margin-top:16px}.step{padding:9px 6px;border-radius:9px;text-align:center;background:#102235;color:#71889c;font-size:12px;border:1px solid transparent}.step.active{color:var(--cyan);border-color:var(--cyan);box-shadow:0 0 16px #42d9e833}.step.done{color:var(--green);border-color:#255c46}.journal{margin-top:14px;max-height:215px;overflow:auto}.event{display:grid;grid-template-columns:80px 1fr;gap:10px;border-left:2px solid #29465e;padding:6px 10px;color:var(--muted)}.event b{color:var(--text)}.empty{height:100%;display:grid;place-items:center;color:var(--muted);text-align:center}.notice{padding:10px;border-radius:9px;background:#172d42;color:var(--muted);font-size:13px}@media(max-width:850px){.grid{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,1fr)}.loop{grid-template-columns:repeat(3,1fr)}}
</style></head><body><main class="shell">
<header><div><h1>Crumblr Static Trainer</h1><p>Eén strategie, één dataset, één autonome verbeterloop.</p></div><span id="health" class="badge">Verbinden…</span></header>
<div class="grid"><section class="panel stack"><div><h2>1. Verbinden</h2><input id="key" type="password" placeholder="Trainer API-key"><div class="row" style="margin-top:9px"><button id="connect">Verbinden</button></div></div>
<div id="strategySlot" class="slot"><strong>2. Strategie</strong><small id="strategyText">Upload één ZIP met MQ5, SET en trainer-strategy.json.</small><div class="row" style="margin-top:10px"><label class="filebtn secondary" for="strategyFile">Strategiepakket kiezen</label><input id="strategyFile" type="file" accept=".zip"></div></div>
<div id="dataSlot" class="slot"><strong>3. Historische data</strong><small id="dataText">Upload één candle-CSV. Deze blijft tijdens de actieve gratis testsessie opgeslagen.</small><div class="row" style="margin-top:10px"><label class="filebtn secondary" for="dataFile">Databestand kiezen</label><input id="dataFile" type="file" accept=".csv"></div></div>
<button id="start" class="start" disabled>Start verbeterloop</button><button id="pause" class="secondary" hidden>Pauzeren</button><div id="message" class="error"></div><div class="notice">De Trainer doet alleen research. Een kandidaat wordt nooit automatisch live gezet.</div></section>
<section class="panel"><h2>Verbetercurve</h2><div class="metrics"><div class="metric"><span>Baseline profit</span><strong id="baseProfit">—</strong></div><div class="metric"><span>Beste profit</span><strong id="bestProfit">—</strong></div><div class="metric"><span>Verbetering</span><strong id="improvement">—</strong></div><div class="metric"><span>Beste drawdown</span><strong id="drawdown">—</strong></div></div>
<div class="chart" id="chart"><div class="empty">Upload strategie en data om de verbetercurve te starten.</div></div>
<div class="loop" id="loop"></div><p id="current" style="margin-top:12px">Trainer wacht op invoer.</p><div class="journal" id="journal"></div></section></div></main>
<script>
const $=id=>document.getElementById(id);let state={overview:null,strategy:null,campaign:null,busy:false};
const steps=["JOURNAL","WAARNEMING","HYPOTHESE","TEST","CONCLUSIE","VOLGENDE_STAP"];
function auth(){const key=$("key").value.trim();return key?{"Authorization":"Bearer "+key}:{} }
async function api(path,opt={}){const response=await fetch(path,{...opt,headers:{"Content-Type":"application/json",...auth(),...(opt.headers||{})}});let body={};try{body=await response.json()}catch{}if(!response.ok)throw Error(body.message||("HTTP "+response.status));return body}
function storeKey(){localStorage.setItem("crumblr_static_trainer_key",$("key").value.trim())}
function b64(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(",")[1]);r.onerror=reject;r.readAsDataURL(file)})}
function latest(items){return (items||[]).slice().sort((a,b)=>String(b.created_at||"").localeCompare(String(a.created_at||"")))[0]}
async function connect(){storeKey();await refresh()}
async function refresh(){try{const health=await api("/healthz");$("health").textContent="Trainer online";$("health").className="badge ok";state.overview=await api("/api/v1/overview");derive();render()}catch(e){$("message").textContent=e.message;$("health").textContent="Niet verbonden"}}
function derive(){state.strategy=latest(state.overview.strategies);const campaigns=(state.overview.campaigns||[]).filter(c=>!state.strategy||c.strategy_key===state.strategy.strategy_key);state.campaign=latest(campaigns)}
async function uploadStrategy(file){if(!file)return;if(!file.name.toLowerCase().endsWith(".zip")){return fail("Kies één ZIP-bestand met MQ5, SET en trainer-strategy.json.")}busy(true,"Strategie wordt opgeslagen…");try{const result=await api("/api/v1/strategies/import",{method:"POST",body:JSON.stringify({files:[{name:file.name,content_base64:await b64(file)}]})});state.strategy=result;await refresh()}catch(e){fail(e.message)}finally{busy(false)}}
async function ensureCampaign(){if(state.campaign&&state.campaign.strategy_key===state.strategy.strategy_key&&!state.campaign.historical_dataset)return state.campaign;if(state.campaign&&state.campaign.historical_dataset)throw Error("Deze dataset is al opgeslagen. Gebruik de bestaande campagne of maak de testomgeving leeg.");return api("/api/v1/campaigns",{method:"POST",body:JSON.stringify({strategy_key:state.strategy.strategy_key,mode:"MODE_1",objective:"Optimaliseer de bestaande strategie zelfstandig op bevroren historische data.",allowed_changes:["TP","TakeProfitR","exits","SL","SLBufferPoints","break-even","entries","filters","MaxBarsToConfirm","MinFVGSizePoints","EntryExpiryBars","risk"],forbidden_changes:["live trading","broker credentials","automatic promotion"],max_experiments:20,max_variants:20,max_runtime_minutes:60,development_dataset:"uploaded-static-dataset",validation_method:"random rolling OOS sealed holdout"})})}
async function uploadData(file){if(!file)return;if(!state.strategy)return fail("Upload eerst het strategie-ZIP.");busy(true,"Data wordt opgeslagen en baseline wordt berekend…");try{state.campaign=await ensureCampaign();await api("/api/v1/campaigns/"+encodeURIComponent(state.campaign.campaign_id)+"/historical-candles",{method:"POST",body:JSON.stringify({file:{name:file.name,content_base64:await b64(file)}})});await refresh()}catch(e){fail(e.message)}finally{busy(false)}}
async function start(){if(!state.campaign||!state.campaign.historical_dataset)return;busy(true,"Verbeterloop wordt gestart…");try{await api("/api/v1/campaigns/"+encodeURIComponent(state.campaign.campaign_id)+"/agent/run",{method:"POST",body:"{}"});await refresh()}catch(e){fail(e.message)}finally{busy(false)}}
async function pause(){try{await api("/api/v1/campaigns/"+encodeURIComponent(state.campaign.campaign_id)+"/agent/pause",{method:"POST",body:"{}"});await refresh()}catch(e){fail(e.message)}}
function fail(text){$("message").textContent=text}function busy(on,text){state.busy=on;if(text!==undefined)$("message").textContent=text;$("start").disabled=on||!(state.campaign&&state.campaign.historical_dataset)}
function esc(value){return String(value??"").replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch]))}
function metric(value,d=2){return Number.isFinite(value)?value.toFixed(d)+"R":"—"}
function render(){const s=state.strategy,c=state.campaign,experiments=(state.overview.experiments||[]).filter(e=>c&&e.campaign_id===c.campaign_id&&e.result);$("strategySlot").classList.toggle("ready",!!s);$("strategyText").textContent=s?(s.name+" · "+s.version+" · "+s.instrument+" "+s.timeframe):"Upload één ZIP met MQ5, SET en trainer-strategy.json.";const hasData=!!(c&&c.historical_dataset);$("dataSlot").classList.toggle("ready",hasData);$("dataText").textContent=hasData?(c.historical_dataset.candle_count+" candles opgeslagen · actieve testsessie"):("Upload één candle-CSV. Na een Render-restart moet dit opnieuw.");$("start").disabled=state.busy||!hasData;const running=c&&c.automation&&c.automation.state==="RUNNING";$("pause").hidden=!running;$("start").textContent=running?"Verbeterloop actief":(c&&c.automation&&c.automation.state==="PAUSED"?"Hervat verbeterloop":"Start verbeterloop");renderCurve(c,experiments);renderLoop(c)}
function renderCurve(c,experiments){const base=c&&c.baseline_result&&c.baseline_result.metrics||null;const points=base?[base.net_r,...experiments.map(e=>e.result.metrics.net_r)]:[];const best=points.length?Math.max(...points):null;$("baseProfit").textContent=base?metric(base.net_r):"—";$("bestProfit").textContent=best===null?"—":metric(best);$("improvement").textContent=base&&best!==null?metric(best-base.net_r):"—";const bestExp=experiments.slice().sort((a,b)=>b.result.metrics.net_r-a.result.metrics.net_r)[0];$("drawdown").textContent=bestExp?metric(bestExp.result.metrics.max_drawdown_r):(base?metric(base.max_drawdown_r):"—");if(!points.length){$("chart").innerHTML='<div class="empty">Upload strategie en data om de verbetercurve te starten.</div>';return}const w=760,h=270,p=32,min=Math.min(...points,0),max=Math.max(...points,0),range=Math.max(max-min,.01);const xy=points.map((v,i)=>[(p+i*(w-2*p)/Math.max(points.length-1,1)),h-p-(v-min)*(h-2*p)/range]);const path=xy.map((q,i)=>(i?'L':'M')+q[0].toFixed(1)+' '+q[1].toFixed(1)).join(' '),dots=xy.map((q,i)=>'<circle cx="'+q[0]+'" cy="'+q[1]+'" r="'+(i?4:6)+'" fill="'+(i?'#42d9e8':'#ffc967')+'"><title>'+(i?'Test '+i:'Baseline')+': '+points[i].toFixed(2)+'R</title></circle>').join('');$("chart").innerHTML='<div class="legend">● baseline &nbsp; <span style="color:#42d9e8">● tests</span></div><svg viewBox="0 0 '+w+' '+h+'"><line x1="'+p+'" y1="'+(h-p)+'" x2="'+(w-p)+'" y2="'+(h-p)+'" stroke="#29465e"/><path d="'+path+'" fill="none" stroke="#42d9e8" stroke-width="3"/>'+dots+'</svg>'}
function renderLoop(c){const activity=(state.overview.agent_activity||[]).find(a=>c&&a.campaign_id===c.campaign_id),trace=activity&&activity.technical_trace||[],active=trace.length?trace[trace.length-1].step:"";$("loop").innerHTML=steps.map(step=>'<div class="step '+(step===active?'active':trace.some(e=>e.step===step)?'done':'')+'">'+step.replace('_',' ')+'</div>').join('');$("current").textContent=activity?(activity.label+" — "+(activity.detail||"")):(c&&c.historical_dataset?"Baseline gereed. Start de verbeterloop.":"Trainer wacht op invoer.");$("journal").innerHTML=trace.slice(-12).reverse().map(e=>'<div class="event"><span>'+esc(String(e.at||'').slice(11,19))+'</span><div><b>'+esc(e.step)+'</b><br>'+esc(e.message)+'</div></div>').join('')}
$("connect").onclick=connect;$("strategyFile").onchange=e=>uploadStrategy(e.target.files[0]);$("dataFile").onchange=e=>uploadData(e.target.files[0]);$("start").onclick=start;$("pause").onclick=pause;$("key").value=localStorage.getItem("crumblr_static_trainer_key")||"";if($("key").value)refresh();setInterval(()=>{if(state.overview)refresh()},3000);
</script></body></html>'''
